import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] p = new double[n];
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
        }

        int count_nonzero = 0;
        for (double prob : p) {
            if (prob > 1e-6) {
                count_nonzero++;
            }
        }

        if (count_nonzero <= k) {
            for (double prob : p) {
                System.out.print((prob > 1e-6 ? "1 " : "0 "));
            }
            System.out.println();
            return;
        }

        double[] answer = new double[n];
        double[] dp = new double[1 << n];
        dp[0] = 1.0;

        for (int mask = 0; mask < (1 << n); mask++) {
            double total_prob = 0.0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    total_prob += p[i];
                }
            }
            if (total_prob >= 0.99999) continue;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int nextMask = mask | (1 << i);
                dp[nextMask] += dp[mask] * p[i] / (1 - total_prob);
            }
        }

        for (int mask = 0; mask < (1 << n); mask++) {
            int bitsCount = Integer.bitCount(mask);
            if (bitsCount != k) continue;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    answer[i] += dp[mask];
                }
            }
        }

        for (double val : answer) {
            System.out.printf("%.13f ", val);
        }
        System.out.println();
    }
}
